n=30; g=[[0]*n for _ in range(n)]; starts=[1,8,15,22,29]; colors=[[3,2,2,3,4],[2,8,8,2,4],[3,2,2,3,4],[2,8,8,2,4],[4,4,4,4,4]]
# tiles 5x5 with interior 3x3 and border 4, last truncated; actual row4 all border at row29
for i,r in enumerate(starts):
 for j,c in enumerate(starts):
  col=colors[i][j]
  for y in range(r,min(r+5,n)):
   for x in range(c,min(c+5,n)):
    g[y][x]=4 if y in (r,r+4) or x in (c,c+4) else col
# Extend tile interior colors across immediately adjacent zero gaps in row/column, aligned with interiors.
# horizontal gap between tile columns, within each tile-row interior height
for i,r in enumerate(starts):
 for j in range(4):
  a,b=starts[j],starts[j+1]; col=colors[i][j]
  for y in range(r+1,min(r+4,n)):
   for x in range(a+5,b):
    g[y][x]=col
# vertical gaps: corresponding interior width, color from upper tile
for i in range(4):
 for j,c in enumerate(starts):
  a,b=starts[i],starts[i+1]; col=colors[i][j]
  for y in range(a+5,b):
   for x in range(c+1,min(c+4,n)):
    g[y][x]=col
import json
print(json.dumps(g))

# reconstruct accurate: for each special tile, rays on center row/column through zero gaps until edge / next tile; only gap spaces
G=[[0]*30 for _ in range(30)]; st=[1,8,15,22,29]; C=[[3,2,2,3,2],[2,8,8,2,2],[3,2,2,3,2],[2,8,8,2,2],[2]*5]
for i,r in enumerate(st):
 for j,c in enumerate(st):
  for y in range(r,min(r+5,30)):
   for x in range(c,min(c+5,30)): G[y][x]=4 if y in (r,r+4) or x in (c,c+4) else C[i][j]
# rays from center of exceptional tiles 3 or 8 along center line through gaps only
for i,r in enumerate(st):
 for j,c in enumerate(st):
  z=C[i][j]
  if z not in (3,8): continue
  cy,cx=r+2,c+2
  # rays in cardinal dirs, overwrite only zeros; stop when hit nonzero tile
  for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
   y,x=cy+dy,cx+dx
   while 0<=y<30 and 0<=x<30:
    if G[y][x]!=0: break
    G[y][x]=z; y+=dy; x+=dx
import json
print(json.dumps(G))

# G base and fill gap segments on center row/col of anomalous tiles, entire tile-grid lines
G=[[0]*30 for _ in range(30)]; st=[1,8,15,22,29]; C=[[3,2,2,3,2],[2,8,8,2,2],[3,2,2,3,2],[2,8,8,2,2],[2]*5]
for i,r in enumerate(st):
 for j,c in enumerate(st):
  for y in range(r,min(r+5,30)):
   for x in range(c,min(c+5,30)): G[y][x]=4 if y in (r,r+4) or x in (c,c+4) else C[i][j]
for i,r in enumerate(st):
 for j,c in enumerate(st):
  z=C[i][j]
  if z not in (3,8): continue
  cy,cx=r+2,c+2
  for dy,dx in ((0,1),(0,-1)):
   x=cx+dx
   while 0<=x<30 and G[cy][x]==0: G[cy][x]=z;x+=dx
  for dy,dx in ((1,0),(-1,0)):
   y=cy+dy
   while 0<=y<30 and G[y][cx]==0: G[y][cx]=z;y+=dy
import json
print(json.dumps(G))

# paint only gap centers directed outward from each exceptional tile
for i,r in enumerate(st):
 for j,c in enumerate(st):
  z=C[i][j]
  if z not in (3,8): continue
  cy,cx=r+2,c+2
  for jj in range(j+1,5):
   for x in range(c+5,st[jj]): G[cy][x]=z
  for jj in range(j):
   for x in range(st[jj]+5,c): G[cy][x]=z
  for ii in range(i+1,5):
   for y in range(r+5,st[ii]): G[y][cx]=z
  for ii in range(i):
   for y in range(st[ii]+5,r): G[y][cx]=z
